import unittest

from solution import prepare_examples


class PrepareExamplesTests(unittest.TestCase):
    def test_split_order_labels_and_independent_deep_copies(self):
        records = [
            {"pixels": [[1, 2], [3, 4]], "sector": "north", "distance": "near"},
            {"pixels": [[5, 6], [7, 8]], "sector": "south", "distance": "far"},
            {"pixels": [[9, 10], [11, 12]], "sector": "east", "distance": "mid"},
        ]
        result = prepare_examples(records, 2)
        self.assertEqual(result, {
            "sector": {
                "train": [
                    {"pixels": [[1, 2], [3, 4]], "label": "north"},
                    {"pixels": [[9, 10], [11, 12]], "label": "east"},
                ],
                "validation": [{"pixels": [[5, 6], [7, 8]], "label": "south"}],
            },
            "distance": {
                "train": [
                    {"pixels": [[1, 2], [3, 4]], "label": "near"},
                    {"pixels": [[9, 10], [11, 12]], "label": "mid"},
                ],
                "validation": [{"pixels": [[5, 6], [7, 8]], "label": "far"}],
            },
        })

        sector_pixels = result["sector"]["train"][0]["pixels"]
        distance_pixels = result["distance"]["train"][0]["pixels"]
        self.assertIsNot(sector_pixels, records[0]["pixels"])
        self.assertIsNot(sector_pixels[0], records[0]["pixels"][0])
        self.assertIsNot(sector_pixels, distance_pixels)
        self.assertIsNot(sector_pixels[0], distance_pixels[0])

        records[0]["pixels"][0][0] = 200
        self.assertEqual(sector_pixels[0][0], 1)
        sector_pixels[0][1] = 201
        self.assertEqual(distance_pixels[0][1], 2)
        self.assertEqual(records[0]["pixels"][0][1], 2)

    def test_empty_input(self):
        records = []
        result = prepare_examples(records, 2)
        self.assertEqual(result, {
            "sector": {"train": [], "validation": []},
            "distance": {"train": [], "validation": []},
        })
        self.assertEqual(records, [])

    def test_holdout_stride_validation(self):
        for stride in (True, False, 1, 0, -2, 2.0, "2", None):
            with self.subTest(stride=stride), self.assertRaises((TypeError, ValueError)):
                prepare_examples([], stride)

    def test_record_keys_and_text_fields_are_validated(self):
        valid = {"pixels": [[0]], "sector": "s", "distance": "d"}
        malformed = [
            {"pixels": [[0]], "sector": "s"},
            dict(valid, extra=1),
            {"pixels": [[0]], "sector": "", "distance": "d"},
            {"pixels": [[0]], "sector": 1, "distance": "d"},
            {"pixels": [[0]], "sector": "s", "distance": ""},
            {"pixels": [[0]], "sector": "s", "distance": None},
            ["not", "a", "mapping"],
        ]
        for record in malformed:
            with self.subTest(record=record), self.assertRaises((TypeError, ValueError)):
                prepare_examples([record], 2)

    def test_pixel_matrix_validation(self):
        matrices = [
            [],
            [[]],
            [[1, 2], [3]],
            [[True]],
            [[1.5]],
            [["1"]],
            [[-1]],
            [[256]],
            [1, 2],
        ]
        for pixels in matrices:
            record = {"pixels": pixels, "sector": "s", "distance": "d"}
            with self.subTest(pixels=pixels), self.assertRaises((TypeError, ValueError)):
                prepare_examples([record], 2)


if __name__ == "__main__":
    unittest.main()

